csapp-twos-encode.solution:
def t2b(x, w):
    if not (-(1 << (w - 1)) <= x <= (1 << (w - 1)) - 1):
        return "overflow"
    return format(x & ((1 << w) - 1), "0%db" % w)

csapp-sign-extend.solution:
def sign_extend(p, from_w, to_w):
    if (p >> (from_w - 1)) & 1:
        p |= ((1 << to_w) - 1) ^ ((1 << from_w) - 1)
    return p

csapp-tadd-overflow.solution:
def tadd(x, y, w):
    true = x + y
    s = true & ((1 << w) - 1)
    if s >> (w - 1):
        s -= 1 << w
    if true > (1 << (w - 1)) - 1:
        kind = "positive"
    elif true < -(1 << (w - 1)):
        kind = "negative"
    else:
        kind = "none"
    return [s, kind]

csapp-float-decode.solution:
def decode_float(u):
    s = u >> 31
    e = (u >> 23) & 0xFF
    f = u & 0x7FFFFF
    if e == 0xFF:
        if f:
            return "nan"
        return "-inf" if s else "inf"
    if e == 0:
        v = f * 2.0 ** (-149)
    else:
        v = (f + (1 << 23)) * 2.0 ** (e - 150)
    return -v if s else v

csapp-float-round-even.solution:
def round_even(num, k):
    ip, fp = num.split(".")
    fp = fp + "0" * max(0, k - len(fp))
    kept = int(ip + fp[:k], 2)
    rest = fp[k:]
    if rest and rest[0] == "1":
        if "1" in rest[1:] or (kept & 1):
            kept += 1
    s = bin(kept)[2:]
    if k == 0:
        return s
    s = s.rjust(k + 1, "0")
    return s[:-k] + "." + s[-k:]
